def test_three_dicts_mixed_keys():
    d1 = {"a": 1, "b": 2}
    d2 = {"b": 3, "c": 4}
    d3 = {"c": 5, "a": 6}

    expected = {
        "a": [1, None, 6],
        "b": [2, 3, None],
        "c": [None, 4, 5],
    }

    assert zip_dicts(d1, d2, d3) == expected


