def test_no_dicts_returns_empty():
    assert zip_dicts() == {}


def test_none_vs_missing_values():
    d1 = {"a": None}   # key present with value None
    d2 = {}            # key absent
    expected = {"a": [None, None]}  # both resolve to None via dict.get
    assert zip_dicts(d1, d2) == expected


def test_with_empty_dict_among_others():
    d1 = {}
    d2 = {"x": 10}
    d3 = {}
    expected = {"x": [None, 10, None]}
    assert zip_dicts(d1, d2, d3) == expected


